CREATE TABLE [dbo].[cstotarifa](	  [provedor_id] SMALLINT NOT NULL	, [tipoLlamada_id] SMALLINT NOT NULL	, [minutoUno] DECIMAL(15,3) NOT NULL DEFAULT((0))	, [minutoAdicional] DECIMAL(15,3) NOT NULL DEFAULT((0))	, CONSTRAINT [PK_cstoTarifa] PRIMARY KEY ([provedor_id] ASC, [tipoLlamada_id] ASC))ALTER TABLE [dbo].[cstotarifa] WITH NOCHECK ADD CONSTRAINT [FK_cstoTarifa_cstoProvedor] FOREIGN KEY([provedor_id]) REFERENCES [dbo].[cstoprovedor] ([provedor_id])ALTER TABLE [dbo].[cstotarifa] CHECK CONSTRAINT [FK_cstoTarifa_cstoProvedor]